using UnityEngine;

namespace Game.Core.Navigation
{
    /// <summary>
    /// The recorded GPS sentences (ADR 0328): one AudioClip per <see cref="VoiceClip"/> key GPS_Bxx #i of the pack
    /// (docs/owner/ELEVENLABS-GPS-VOICE.md, tools/audio/gps/pack.py). Generated by the editor importer
    /// (Game.Editor.Audio.GpsVoiceImporter) from Assets/_Project/Audio/Voice/gps_manifest.json into
    /// Assets/_Project/Audio/Generated/Resources/GpsVoice/ (gitignored, rebuilt before every build). Missing bank = silent
    /// GPS with one warning, never an error.
    /// </summary>
    public sealed class NavVoiceBank : ScriptableObject
    {
        public const string ResourcePath = "GpsVoice/NavVoiceBank";
        /// <summary>Largest block / index a key may have (lookup table size).</summary>
        public const int MaxBlock = 31, MaxIndex = 31;

        public byte[] blocks = System.Array.Empty<byte>();
        public byte[] indices = System.Array.Empty<byte>();
        public AudioClip[] clips = System.Array.Empty<AudioClip>();
        [Tooltip("Manifest generator, voice and clip count, for the log.")]
        public string sourceInfo;

        AudioClip[] m_Table;

        public int Count => clips != null ? clips.Length : 0;

        public static int Slot(int block, int index) => block * (MaxIndex + 1) + index;

        /// <summary>The clip of key GPS_B<paramref name="block"/> #<paramref name="index"/>; null when not in the pack. No allocation
        /// after the first call (the lookup table is built once).</summary>
        public AudioClip Get(int block, int index)
        {
            if (block <= 0 || index <= 0 || block > MaxBlock || index > MaxIndex) return null;
            if (m_Table == null) Build();
            return m_Table[Slot(block, index)];
        }

        public AudioClip Get(VoiceClip c) => Get(c.Block, c.Index);

        /// <summary>Rebuilds the lookup after the arrays changed (importer / tests).</summary>
        public void Build()
        {
            m_Table = new AudioClip[(MaxBlock + 1) * (MaxIndex + 1)];
            int n = Mathf.Min(Count, Mathf.Min(blocks.Length, indices.Length));
            for (int i = 0; i < n; i++)
                if (blocks[i] > 0 && indices[i] > 0 && blocks[i] <= MaxBlock && indices[i] <= MaxIndex)
                    m_Table[Slot(blocks[i], indices[i])] = clips[i];
        }

        public static NavVoiceBank LoadDefault() => Resources.Load<NavVoiceBank>(ResourcePath);
    }
}
